#include "results.hpp"

// generated by CMake on every build (cmake/git_version.cmake): GIT_COMMIT, BUILD_TYPE
#include "git_version.hpp"

#include <cstdio>
#include <ctime>
#include <fstream>

namespace {

/// CSV quoting (RFC 4180): fields with commas, quotes or line breaks are put in quotes, quotes are doubled
std::string csvField(const std::string& text)
{
    if (text.find_first_of(",\"\n\r") == std::string::npos)
        return text;
    std::string quoted = "\"";
    for (const char c : text)
        quoted += c == '"' ? std::string("\"\"") : std::string(1, c);
    return quoted + '"';
}

} // namespace

void Results::add(const std::string& name, double value)
{
    // 17 significant digits represent every double exactly
    char text[32];
    std::snprintf(text, sizeof(text), "%.17g", value);
    mColumns.emplace_back(name, text);
}

void Results::addRunEnvironment(const std::string& runName, const std::string& device, const std::string& timingCaveats)
{
    const std::time_t now = std::time(nullptr);
    char timestamp[32];
    std::strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", std::localtime(&now));

    add("run_name", runName);
    add("timestamp", timestamp);
    add("git_commit", GIT_COMMIT);
    add("build_type", BUILD_TYPE);
    add("device", device);
    add("timing_caveats", timingCaveats);
}

std::string Results::getHeader() const
{
    std::string header;
    for (const auto& [name, value] : mColumns)
        header += (header.empty() ? "" : ",") + csvField(name);
    return header;
}

std::string Results::getRow() const
{
    std::string row;
    for (size_t i = 0; i < mColumns.size(); i++)
        row += (i == 0 ? "" : ",") + csvField(mColumns[i].second);
    return row;
}

std::string Results::toString() const
{
    std::string text;
    for (const auto& [name, value] : mColumns)
        text += (text.empty() ? "" : ", ") + name + "=" + value;
    return text;
}

std::string Results::appendToFile(const std::string& path) const
{
    // the first line of an existing file is its header, it has to match the columns of this row
    std::string existingHeader;
    {
        std::ifstream existing(path);
        std::getline(existing, existingHeader);
    }
    if (!existingHeader.empty() && existingHeader != getHeader())
        return "The columns of " + path
               + " differ from the results of this run (e.g. a new option or timer), use another file.\n  file: "
               + existingHeader + "\n  run:  " + getHeader();

    std::ofstream file(path, std::ios::app);
    if (existingHeader.empty())
        file << getHeader() << "\n";
    file << getRow() << "\n";
    if (!file)
        return "Cannot write to " + path;
    return "";
}
